css:
[data-user-message-bubble]{background:transparent!important;border:0!important;border-left:2px solid #E8974F!important;border-radius:0!important;box-shadow:none!important}
[data-slot="composer-host"]{border-top:1px solid #E8974F!important;box-shadow:none!important}
[data-slot="composer-shell"],[data-slot="composer-shell"]::before,[data-slot="composer-host"],[data-slot="composer-host"]::before,[data-slot="composer-host"]::after,[data-chat-composer-main-surface],[data-chat-composer-main-surface]::after{border-radius:0!important}
[data-thread-details-card]{border-radius:0!important;box-shadow:none!important}
.chat-markdown-codeblock{border-radius:0!important}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3,.chat-markdown h4{font-family:"Lora","Iowan Old Style",Georgia,serif!important;font-weight:600;letter-spacing:0}
.chat-markdown a{color:#E8974F}
[data-chat-composer-form]{position:relative}
[data-slot=sidebar] [data-thread-item] [aria-current=page]{background:transparent!important;border:0!important;border-left:2px solid #E8974F!important;border-radius:0!important;box-shadow:none!important}
[data-slot=sidebar] [data-slot=project-monogram] svg{background:transparent!important;border:1px solid #FFF0DE;border-radius:0!important;box-sizing:border-box;color:#FFF0DE!important}
@property --kg-rise{syntax:"<number>";inherits:false;initial-value:0}@property --kg-focus{syntax:"<number>";inherits:false;initial-value:0}@property --kg-clock{syntax:"<number>";inherits:false;initial-value:0}@property --kg-step{syntax:"<number>";inherits:false;initial-value:0}@property --kg-active{syntax:"<number>";inherits:false;initial-value:0}
[data-chat-composer-form]::before{content:"";position:absolute;right:14px;bottom:100%;width:43px;height:45px;pointer-events:none;z-index:1;--kg-span:max(0,calc((100cqw - 71px)/1px));--kg-time:max(.8s,calc(var(--kg-span)*.024s));--kg-rise:0;--kg-focus:0;--kg-active:0;--kg-busy:0;--kg-phase:calc(1 - abs(1 - var(--kg-clock)));--kg-x:calc(var(--kg-phase)*var(--kg-span)*var(--kg-active));--kg-step:calc(var(--kg-x)*var(--kg-dir)*-.3);--kg-eye:0;--kg-nap:0;--kg-kind:max(var(--kg-busy),clamp(0,sign(var(--kg-x) - .25),1));--kg-dir:calc(1 - 2*var(--kg-busy)*max(0,sign(var(--kg-phase)*min(1,sign(1 - var(--kg-active))) + (1 - 2*round(down,calc(var(--kg-clock)/1),1))*var(--kg-active))));--kg-pose:round(nearest,max(var(--kg-rise),var(--kg-focus)),1);transition:--kg-rise .8s linear var(--kg-time),--kg-focus .8s linear,--kg-active var(--kg-time) linear;translate:calc(clamp(0,var(--kg-x),var(--kg-span))*-1px) 0;scale:calc(1 - var(--kg-kind) + var(--kg-kind)*var(--kg-dir)) 1;background-image:url("data:image/webp;base64,");background-repeat:no-repeat;background-size:774px 45px;background-position:calc(((1 - var(--kg-kind))*(var(--kg-pose) + round(down,calc(var(--kg-pose)/5),1)*var(--kg-eye) + (1 - min(1,var(--kg-pose)))*var(--kg-nap)*7) + var(--kg-kind)*(8 + mod(round(down,var(--kg-step),1),8)))*-43px) 0;animation:kg-eye 3.4s steps(1,end) infinite,kg-nap 3.4s steps(1,end) infinite,kg-patrol calc(var(--kg-time)*2) linear infinite;animation-play-state:running,running,paused}
[data-chat-composer-form]::after{content:"";position:absolute;right:14px;bottom:100%;width:43px;height:45px;pointer-events:none;background:url("data:image/webp;base64,") no-repeat 0 0/43px 45px}
[data-chat-composer-form]:focus-within::before{--kg-focus:5}
@keyframes kg-eye{0%,89%,97%,100%{--kg-eye:0}92%{--kg-eye:1}}
@keyframes kg-nap{0%,100%{--kg-nap:0}50%{--kg-nap:1}}
@keyframes kg-patrol{to{--kg-clock:2}}

[data-slot=composer-host]:has(button:is([aria-label="Stop generation"],[aria-label=Stopping])) [data-chat-composer-form]::before{--kg-rise:5;--kg-active:1;--kg-busy:1;animation-play-state:running;transition:--kg-rise .8s linear,--kg-focus .8s linear,--kg-active var(--kg-time) linear}
@media(prefers-reduced-motion:reduce){[data-chat-composer-form]::before{animation:none!important;transition:none!important;--kg-active:0!important;--kg-clock:0!important;--kg-kind:0!important;translate:none;scale:1}}
.messages-timeline-scroll{padding-bottom:52px!important}
[data-chat-composer-form]{container-type:inline-size}
[data-workspace-area=composer]:is(:has([data-pending-user-input-toggle]),[data-workspace-area=conversation]:has([data-approval-detail=complete])+*) [data-chat-composer-form]::before{--kg-busy:0;--kg-active:0;--kg-rise:5;--kg-pose:calc(16 + var(--kg-nap));--kg-eye:0!important;animation-play-state:running,running,paused;animation-duration:3.4s,.666s,calc(var(--kg-time)*2)}
